} from "./world.js";

export * from "./world.js";

export function createState(seed = 1): State {
  return {
    frame: 0,
    ...SPAWN,
    vx: 0,
    vy: 0,
    grounded: true,
    platform: false,
    coyote: COYOTE_FRAMES,
    buffer: 0,
